-- Refresh only expired, still-requested demo appointments; never change accepted or completed work.
with stale as (
 select id,row_number() over(order by id) n from public.bookings
 where data->>'demoSeed'='upyogi-demo-v1' and booking_status='Requested'
 and (data->>'appointmentDate')::timestamptz < now()
)
update public.bookings b set data=b.data||jsonb_build_object('appointmentDate',to_char((now()+make_interval(days=>stale.n::int)) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')) from stale where b.id=stale.id;
commit;
